  "title": "夜探古刹",
  "scene": "月黑风高之夜，你潜行至一座古刹。周围静悄悄，但隐约听到轻功往返的声音。门派的恩怨在此刻显得格外沉重。古刹里机关重重，你必须小心翼翼。”,
  "goal": "找到隐藏在古刹中的重要线索。",
  "clue": "轻功往返的声音是线索所在。",
  "choices": [
    {"id": "A", "text": "靠近轻功声音的方向”， "outcome": "你发现了一个隐藏的小密室，里面有一张泛黄的藏宝图。但你注意到密室门上有细微的灰尘，留下了一丝足迹。", "result": "success", "next": "next_level"},
    {"id": "B", "text": "四处观察，寻找其他线索", "outcome": "你发现了一扇未上锁的窗户，但里面只有灰尘和蛛网。", "result": "partial", "next": "retry"},
    {"id": "C", "text": "离开此地，返回客栈搜集更多信息", "outcome": "你发现自己错过了那个隐藏的密室，只能返回客栈。", "result": "fail", "next": "retry"}
  ]
}
